_BRANCH_ANALYSIS_SCHEMA_VERSION = 57
_CALL_RE = re.compile(r"\b([A-Za-z_$][A-Za-z0-9_$]*)\s*\(")
_QUALIFIED_CALL_RE = re.compile(
    r"\b(?:[A-Za-z_$][A-Za-z0-9_$]*\s*\.\s*)+([A-Za-z_$][A-Za-z0-9_$]*)\s*\("
)
_QUALIFIED_STATIC_MEMBER_RE = re.compile(
    r"\b(?P<owner>[A-Z][A-Za-z0-9_$]*)\s*\.\s*"
    r"(?P<member>[A-Z][A-Z0-9_$]*)\b"
)
_CLASS_DECL_RE = re.compile(
    r"\b(?:class|interface|enum|record)\s+"
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\b"
)
_NEW_CALL_RE = re.compile(
    r"\bnew\s+(?P<class>[A-Za-z_$][A-Za-z0-9_$.]*)"
    r"(?:\s*<[^;{}()]*>)?\s*\("
)
_FIELD_ASSIGNMENT_RE = re.compile(
    r"^\s*(?P<receiver>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*"
    r"(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)\s*="
)
_LOCAL_DECLARATION_RE = re.compile(
    r"^\s*(?:final\s+)?"
    r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.\[\]]*)\s+"
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
    r"(?P<rhs>.+?)\s*;?\s*$"
)
_METHOD_DECL_RE = re.compile(
    r"(?m)^[ \t]*"
    r"(?:@[A-Za-z_$][A-Za-z0-9_$.]*(?:\([^)\r\n]*\))?[ \t]+)*"
    r"(?:(?P<access>public|protected|private)\s+)?"
    r"(?P<modifiers>"
    r"(?:(?:static|final|synchronized|abstract|native|strictfp|default)\s+)*)"
    r"(?:<[^>{};]+>\s+)?"
    r"(?!(?:public|protected|private)\b)"
    # Keep the declaration head line-bounded. Allowing ``\s`` here makes the
    # regex scan across method bodies and can trigger catastrophic backtracking
    # on large Java sources. Multiline parameter lists remain supported by the
    # balanced-parenthesis parser that runs after this match.
    r"[A-Za-z_$][A-Za-z0-9_$<>\[\].?, \t]*?[ \t]+"
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*\("
)
_FIELD_DECL_RE = re.compile(
    r"(?m)^[ \t]*(?:(?:public|protected|private)\s+)?"
    r"(?:(?:static|final|transient|volatile)\s+)*"
    r"[A-Za-z_$][A-Za-z0-9_$<>\[\].?,\s]*?\s+"
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*(?:=|;)"
)
_FIELD_CONTRACT_RE = re.compile(
    r"(?m)^[ \t]*(?:(?P<access>public|protected|private)\s+)?"
    r"(?:(?:static|final|transient|volatile)\s+)*"
    r"(?P<type>[A-Za-z_$][A-Za-z0-9_$<>\[\].?,\s]*?)\s+"
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*(?:=|;)"
)
_JAVA_KEYWORDS = {
    "if", "for", "while", "switch", "catch", "return", "throw", "new",
    "super", "this", "synchronized", "assert", "try", "do",
}


