def _is_context_window_rejection(error: object) -> bool:
    """Recognize common OpenAI-compatible context-window diagnostics."""

    text = str(error or "").lower()
    if not text:
        return False
    explicit_markers = (
        "context length",
        "context window",
        "context size",
        "maximum context",
        "max context",
        "n_ctx",
        "n_keep",
        "too many tokens",
        "input is too long",
        "prompt is too long",
    )
    overflow_markers = (
        "exceed",
        "greater than",
        "too long",
        "too many",
        "maximum",
        "max ",
        ">=",
    )
    return any(marker in text for marker in explicit_markers) and any(
        marker in text for marker in overflow_markers
    )


def _context_rejection_retry_fraction(error: object) -> float:
    """Return a conservative evidence-budget scale for one retry.

    LM Studio/llama.cpp commonly reports both ``n_keep`` and ``n_ctx``. The
    complete request also contains fixed instructions and a response schema,
    so leave a safety margin instead of scaling the evidence object to the
    bare reported ratio.
    """

    text = str(error or "")
    keep_match = re.search(r"\bn_keep\s*:\s*(\d+)", text, re.IGNORECASE)
    ctx_match = re.search(r"\bn_ctx\s*:\s*(\d+)", text, re.IGNORECASE)
    if keep_match and ctx_match:
        keep = max(1, int(keep_match.group(1)))
        context = max(1, int(ctx_match.group(1)))
        return max(0.3, min(0.7, (context / keep) * 0.65))
    return 0.55


def _semantic_subcall_context_max_chars(
    *,
    api_base: str,
    main_context_max_chars: int,
) -> int:
    """Bound correction/state-trace evidence below the main analysis budget."""

    default_limit = 24000 if is_local_lmstudio_base(api_base) else 36000
    configured = os.environ.get(
        "TATG_BRANCH_ANALYSIS_SUBCALL_CONTEXT_MAX_CHARS"
    )
    if configured is not None:
        try:
            default_limit = max(8000, int(configured or default_limit))
        except (TypeError, ValueError):
            pass
    return max(
        8000,
        min(
            int(default_limit),
            max(8000, int(main_context_max_chars or default_limit)),
        ),
    )


def _branch_analysis_stage_timeout_seconds(
    *,
    api_base: str,
    requested_timeout: int | float,
) -> int:
    """Return the total bounded budget shared by semantic analysis subcalls.

    A single local request timeout is not a usable total budget when the
    source-validated pipeline deliberately performs classification, causal
    tracing, setup synthesis, and feasibility verification as separate calls.
    Remote-provider behavior remains unchanged unless explicitly configured.
    """

    try:
        requested = max(1, int(float(requested_timeout)))
    except Exception:
        requested = 1
    default = requested * 4 if is_local_lmstudio_base(api_base) else requested
    configured = os.environ.get(
        "TATG_BRANCH_ANALYSIS_STAGE_TIMEOUT_SECONDS"
    )
    if configured is None:
        return default
    try:
        return max(1, int(configured or default))
    except (TypeError, ValueError):
        return default


def _semantic_context_json_chars(value: object) -> int:
    return len(json.dumps(value, ensure_ascii=True, separators=(",", ":")))


def _budget_semantic_analysis_context(
    context: dict[str, Any],
    *,
    max_chars: int,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Keep semantic evidence as complete items within one bounded context.

    Branch predicates and the target method body are authoritative and are
    never clipped mid-field. Lists and mappings are added item-by-item in
    evidence priority order; an item that does not fit is omitted whole and
    counted in the audit. This keeps local OpenAI-compatible servers from
    rejecting an otherwise valid analysis request while avoiding malformed
    half source facts.
    """

    original_chars = _semantic_context_json_chars(context)
    budget = max(1, int(max_chars or 0))
    output: dict[str, Any] = {}
    omitted_by_key: dict[str, int] = {}
    emitted_item_counts: dict[str, int] = {}
    # These are compact execution contracts, not broad source context. Keep
    # them intact so compaction cannot leave the model with a branch predicate
    # but no legal constructor/entry recipe. Large method/signature inventories
    # remain item-compacted below.
    protected_keys = {
        "target",
        "branch_control_dataflow_slices",
        "verified_public_or_package_entry_methods",
        "verified_public_or_package_entry_contracts",
        "source_visible_constructors",
        "source_visible_constructor_arities",
        "source_visible_receiver_setup_recipes",
    }

    ordered_keys = [
        key for key in _SEMANTIC_CONTEXT_KEY_PRIORITY if key in context
    ]
    ordered_keys.extend(
        key for key in context if key not in set(ordered_keys)
    )

    def fits(candidate: dict[str, Any]) -> bool:
        return _semantic_context_json_chars(candidate) <= budget

    for key in ordered_keys:
        value = context[key]
        if key in protected_keys:
            candidate = {**output, key: value}
            if fits(candidate):
                output[key] = value
            else:
                omitted_by_key[key] = omitted_by_key.get(key, 0) + 1
            continue
        if isinstance(value, list):
            accepted: list[Any] = []
            cap = _SEMANTIC_CONTEXT_ITEM_CAPS.get(key, len(value))
            for item_index, item in enumerate(value):
                if item_index >= cap:
                    omitted_by_key[key] = (
                        omitted_by_key.get(key, 0) + 1
                    )
                    continue
                candidate = {**output, key: [*accepted, item]}
                if fits(candidate):
                    accepted.append(item)
                else:
                    omitted_by_key[key] = omitted_by_key.get(key, 0) + 1
            final_candidate = {**output, key: accepted}
            if accepted or (not value and fits(final_candidate)):
                output[key] = accepted
                emitted_item_counts[key] = len(accepted)
            elif not value:
                omitted_by_key[key] = omitted_by_key.get(key, 0) + 1
            continue
        if isinstance(value, dict):
            accepted_mapping: dict[str, Any] = {}
            cap = _SEMANTIC_CONTEXT_ITEM_CAPS.get(key, len(value))
            for item_index, (item_key, item_value) in enumerate(
                value.items()
            ):
                if item_index >= cap:
                    omitted_by_key[key] = (
                        omitted_by_key.get(key, 0) + 1
                    )
                    continue
                candidate = {
                    **output,
                    key: {**accepted_mapping, item_key: item_value},
                }
                if fits(candidate):
                    accepted_mapping[item_key] = item_value
                else:
                    omitted_by_key[key] = omitted_by_key.get(key, 0) + 1
            final_candidate = {**output, key: accepted_mapping}
            if accepted_mapping or (not value and fits(final_candidate)):
                output[key] = accepted_mapping
                emitted_item_counts[key] = len(accepted_mapping)
            elif not value:
                omitted_by_key[key] = omitted_by_key.get(key, 0) + 1
            continue
        candidate = {**output, key: value}
        if fits(candidate):
            output[key] = value
        else:
            omitted_by_key[key] = omitted_by_key.get(key, 0) + 1

    emitted_chars = _semantic_context_json_chars(output)
    audit = {
        "max_chars": budget,
        "original_chars": original_chars,
        "emitted_chars": emitted_chars,
        "compacted": emitted_chars < original_chars,
        "protected_keys": sorted(protected_keys),
        "protected_content_over_budget": emitted_chars > budget,
        "omitted_item_count": sum(omitted_by_key.values()),
        "omitted_by_key": omitted_by_key,
        "emitted_item_counts": emitted_item_counts,
    }
    return output, audit


def _branch_control_dataflow_slices(
    source_text: str,
    *,
    method_name: str,
    anchors: list[dict[str, Any]],
    target_prefix_state_mutations: list[dict[str, Any]] | None = None,
    context_radius: int = 2,
    max_slices: int = 8,
) -> list[dict[str, Any]]:
    """Return compact, line-addressable source around current branch evidence.

    This function deliberately does not infer protocol, parser, codec, or state
    semantics. It selects source solely from coverage anchors, their explicit
    control paths, predecessor exit guards, and exact target-owned writes found
    by the structural scanner. The semantic model can reason over these slices;
    candidate-level replay remains the authority for the inferred behavior.

    Keeping this evidence separate from ``target_method_source`` matters for
    very large methods: whole-item context compaction may omit an oversized
    method body, but it should never leave the model with a branch label and no
    surrounding control/dataflow source.
    """

    lines = str(source_text or "").splitlines()
    if not lines or not anchors:
        return []
    radius = max(0, min(6, int(context_radius or 0)))
    limit = max(0, int(max_slices or 0))
    if limit == 0:
        return []

    mutations_by_anchor: dict[int, list[int]] = {}
    for mutation in list(target_prefix_state_mutations or []):
        if not isinstance(mutation, dict):
            continue
        try:
            anchor_line = int(mutation.get("anchor_line") or 0)
            write_line = int(mutation.get("write_line") or 0)
        except (TypeError, ValueError):
            continue
        if anchor_line > 0 and write_line > 0:
            mutations_by_anchor.setdefault(anchor_line, []).append(write_line)

    requested: list[dict[str, Any]] = []
    for anchor_index, anchor in enumerate(anchors):
        if not isinstance(anchor, dict):
            continue
        try:
            anchor_line = int(anchor.get("line") or 0)
        except (TypeError, ValueError):
            anchor_line = 0
        if anchor_line <= 0 or anchor_line > len(lines):
            continue
        method_span = find_method_line_span_at(
            source_text,
            method_name,
            anchor_line,
        )
        if method_span is None:
            continue
        method_start, method_end = method_span
        evidence_lines: dict[int, set[str]] = {}

        def add_line(value: object, reason: str) -> None:
            try:
                line_no = int(value or 0)
            except (TypeError, ValueError):
                return
            if method_start <= line_no <= method_end:
                evidence_lines.setdefault(line_no, set()).add(reason)

        add_line(anchor_line, "coverage_anchor")
        add_line(anchor.get("governing_control_line"), "governing_control")
        for node in list(anchor.get("control_path") or []):
            if isinstance(node, dict):
                add_line(node.get("line"), "enclosing_control")
                for predecessor in list(
                    node.get("predecessor_conditions") or []
                ):
                    if isinstance(predecessor, dict):
                        add_line(
                            predecessor.get("line"),
                            "control_predecessor",
                        )
        for guard in list(anchor.get("predecessor_exit_guards") or []):
            if isinstance(guard, dict):
                add_line(guard.get("line"), "predecessor_exit_guard")
        for write_line in mutations_by_anchor.get(anchor_line, []):
            add_line(write_line, "target_owned_write")
        if not evidence_lines:
            continue

        ranges = sorted(
            (
                max(method_start, line_no - radius),
                min(method_end, line_no + radius),
            )
            for line_no in evidence_lines
        )
        merged: list[list[int]] = []
        for start, end in ranges:
            if merged and start <= merged[-1][1] + 1:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        for start, end in merged:
            reasons = sorted({
                reason
                for line_no, line_reasons in evidence_lines.items()
                if start <= line_no <= end
                for reason in line_reasons
            })
            requested.append({
                "anchor_index": anchor_index,
                "anchor_line": anchor_line,
                "source_line_start": start,
                "source_line_end": end,
                "evidence_reasons": reasons,
                "source": "\n".join(
                    f"L{line_no}: {lines[line_no - 1]}"
                    for line_no in range(start, end + 1)
                ),
                "proof_status": (
                    "exact_source_context_requires_candidate_replay"
                ),
            })

    # Prefer slices carrying more distinct evidence kinds, then preserve source
    # order. This is a budget choice, not a semantic family classifier.
    requested.sort(
        key=lambda row: (
            -len(list(row.get("evidence_reasons") or [])),
            int(row.get("source_line_start") or 0),
            int(row.get("anchor_index") or 0),
        )
    )
    selected = requested[:limit]
    selected.sort(
        key=lambda row: (
            int(row.get("source_line_start") or 0),
            int(row.get("anchor_index") or 0),
        )
    )
    for index, row in enumerate(selected, start=1):
        row["slice_id"] = f"BS{index}"
    return selected


def _target_prefix_state_mutations(
    source_text: str,
    *,
    method_name: str,
    anchors: list[dict[str, Any]],
    persistent_parameter_roots: set[str] | None = None,
) -> list[dict[str, Any]]:
    """Expose exact target-owned writes that can feed a branch anchor.

    Writes before an anchor describe the current invocation. A persistent
    receiver-field write after an early anchor is also relevant because a
    prior invocation may execute it before the next invocation evaluates the
    anchor. Both are temporal evidence, not symbolic execution results. A
    narrow causal trace and sandbox replay must still prove the controlling
    input and call order.
    """

    lines = str(source_text or "").splitlines()
    out: list[dict[str, Any]] = []
    seen: set[tuple[int, int, str, str, str]] = set()
    recurrent_effects_seen: set[tuple[int, str, str, str]] = set()
    recurrent_counts: dict[tuple[int, str], int] = {}
    declared_fields = {
        str(item.get("name") or "").strip()
        for item in _source_field_contracts(source_text)
        if str(item.get("name") or "").strip()
    }
    persistent_parameter_roots = {
        str(item or "").strip()
        for item in set(persistent_parameter_roots or set())
        if str(item or "").strip()
    }
    write_re = re.compile(
        r"(?<![A-Za-z0-9_$])"
        r"(?P<symbol>(?:this\.)?[A-Za-z_$][A-Za-z0-9_$]*"
        r"(?:\s*\.\s*[A-Za-z_$][A-Za-z0-9_$]*)*)\s*"
        r"(?P<operator>\+\+|--|>>>?=|<<=|[+\-*/%&|^]="
        r"|(?<![=!<>])=(?!=))"
    )
    symbol_re = re.compile(
        r"(?<![A-Za-z0-9_$])"
        r"(?:this\.)?[A-Za-z_$][A-Za-z0-9_$]*"
        r"(?:\s*\.\s*[A-Za-z_$][A-Za-z0-9_$]*)*"
    )
    for anchor in anchors:
        if not isinstance(anchor, dict):
            continue
        try:
            anchor_line = int(anchor.get("line") or 0)
        except (TypeError, ValueError):
            continue
        if anchor_line <= 0 or anchor_line > len(lines):
            continue
        span = find_method_line_span_at(
            source_text,
            method_name,
            anchor_line,
        )
        if span is None:
            continue
        method_start, method_end = span
        reference_text = " ".join(
            [
                str(anchor.get("governing_control") or ""),
                *[
                    str(node.get("statement") or "")
                    for node in list(anchor.get("control_path") or [])
                    if isinstance(node, dict)
                ],
            ]
        )
        if not reference_text.strip():
            reference_text = str(
                anchor.get("logical_statement")
                or anchor.get("code")
                or ""
            )
        referenced_symbols = {
            re.sub(r"\s+", "", match.group(0))
            for match in symbol_re.finditer(reference_text)
            if str(match.group(0) or "").strip()
            and str(match.group(0) or "").strip() not in _JAVA_KEYWORDS
        }
        control_path_lines = [
            int(node.get("line") or 0)
            for node in [
                *list(anchor.get("control_path") or []),
                *list(anchor.get("predecessor_exit_guards") or []),
            ]
            if isinstance(node, dict)
            and str(node.get("line") or "").isdigit()
            and int(node.get("line") or 0) > 0
        ]
        mutation_scan_start = max(
            1,
            method_start,
            min(control_path_lines)
            if control_path_lines
            else method_start,
        )
        scan_ranges = [
            (
                mutation_scan_start,
                anchor_line,
                "current_invocation_before_anchor",
            )
        ]
        if method_end > anchor_line:
            scan_ranges.append((
                anchor_line + 1,
                method_end + 1,
                "prior_invocation_after_anchor_candidate",
            ))
        for scan_start, scan_end, write_phase in scan_ranges:
            for line_no in range(scan_start, scan_end):
                source_line = lines[line_no - 1]
                for match in write_re.finditer(
                    _mask_java_comments(source_line)
                ):
                    symbol = re.sub(
                        r"\s+",
                        "",
                        str(match.group("symbol") or ""),
                    )
                    if not symbol:
                        continue
                    normalized_symbol = re.sub(r"^this\.", "", symbol)
                    if (
                        symbol not in referenced_symbols
                        and normalized_symbol not in referenced_symbols
                    ):
                        continue
                    root = normalized_symbol.split(".", 1)[0]
                    if root in declared_fields:
                        state_carrier_kind = "receiver_field"
                    elif (
                        "." in normalized_symbol
                        and root in persistent_parameter_roots
                    ):
                        state_carrier_kind = "parameter_object_field"
                    elif "." in normalized_symbol:
                        state_carrier_kind = "qualified_state_carrier"
                    else:
                        state_carrier_kind = "method_local"
                    # A local written after an early anchor cannot persist into
                    # the next invocation. Excluding it also prevents ordinary
                    # temporaries such as ``t`` from being promoted to receiver
                    # state merely because they appear in a branch predicate.
                    if (
                        write_phase
                        == "prior_invocation_after_anchor_candidate"
                        and state_carrier_kind
                        not in {"receiver_field", "parameter_object_field"}
                    ):
                        continue
                    operator = str(match.group("operator") or "")
                    if (
                        write_phase
                        == "prior_invocation_after_anchor_candidate"
                    ):
                        compact_effect = re.sub(
                            r"[(){};\s]+",
                            "",
                            re.sub(
                                r"\breturn\b",
                                "",
                                _mask_java_comments(source_line),
                            ),
                        )
                        effect_key = (
                            anchor_line,
                            normalized_symbol,
                            operator,
                            compact_effect,
                        )
                        count_key = (anchor_line, normalized_symbol)
                        if (
                            effect_key in recurrent_effects_seen
                            or recurrent_counts.get(count_key, 0) >= 6
                        ):
                            continue
                        recurrent_effects_seen.add(effect_key)
                        recurrent_counts[count_key] = (
                            recurrent_counts.get(count_key, 0) + 1
                        )
                    key = (
                        anchor_line,
                        line_no,
                        symbol,
                        operator,
                        write_phase,
                    )
                    if key in seen:
                        continue
                    seen.add(key)
                    out.append({
                        "anchor_line": anchor_line,
                        "symbol": symbol,
                        "write_line": line_no,
                        "operator": operator,
                        "write_source": " ".join(source_line.split())[:600],
                        "write_phase": write_phase,
                        "state_carrier_kind": state_carrier_kind,
                        "persistent_across_invocations": (
                            state_carrier_kind
                            in {"receiver_field", "parameter_object_field"}
                        ),
                        "control_path": [
                            {
                                key: node.get(key)
                                for key in (
                                    "line",
                                    "kind",
                                    "statement",
                                    "required_outcome",
                                )
                                if node.get(key) not in (None, "")
                            }
                            for node in list(
                                anchor.get("control_path") or []
                            )[-5:]
                            if isinstance(node, dict)
                        ],
                        "proof_status": (
                            "exact_source_write_requires_prior_invocation_"
                            "reachability"
                            if write_phase
                            == "prior_invocation_after_anchor_candidate"
                            else "exact_source_write_requires_temporal_trace"
                        ),
                    })
    return out[:80]


def _declaration_open_paren(text: str, match: re.Match[str]) -> int:
    """Return the method-parameter ``(``, excluding annotation arguments."""

    return str(text or "").rfind("(", match.start(), match.end())


def _normalized_java_fragment(value: str) -> str:
    return re.sub(r"\s+", "", str(value or ""))


def _causal_symbol_access_path(value: object) -> str:
    """Return one leading Java access path without interpreting its value.

    State-causality responses sometimes restate a catalog symbol as a
    predicate or assignment (for example ``context.eof == true``).  Binding
    that prose by exact string equality loses otherwise valid source facts.
    This helper deliberately extracts only the leading access path; it does
    not infer the predicate outcome or accept method calls/index expressions.
    """

    text = str(value or "").strip()
    text = re.sub(r"^\s*if\s*\(", "", text)
    text = re.sub(r"^[\s(!]+", "", text)
    match = re.match(
        r"(?:(?:this)\s*\.\s*)?"
        r"[A-Za-z_$][A-Za-z0-9_$]*"
        r"(?:\s*\.\s*[A-Za-z_$][A-Za-z0-9_$]*)*",
        text,
    )
    if match is None:
        return ""
    suffix = text[match.end():].lstrip()
    if suffix.startswith(("(", "[")):
        return ""
    access_path = re.sub(r"\s+", "", match.group(0))
    return re.sub(r"^this\.", "", access_path)


def _mask_java_literals(source_text: str) -> str:
    """Mask string/character contents while preserving source offsets."""

    text = _mask_java_comments(source_text)
    chars = list(text)
    quote = ""
    escaped = False
    for index, char in enumerate(text):
        if quote:
            if char not in "\r\n":
                chars[index] = " "
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            continue
        if char in {'"', "'"}:
            quote = char
            chars[index] = " "
    return "".join(chars)


def _enum_constant_members(source_text: str) -> set[str]:
    """Return ``Enum.CONSTANT`` members declared in visible source."""

    scan_text = _mask_java_literals(source_text)
    members: set[str] = set()
    for match in re.finditer(
        r"\benum\s+(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*\{",
        scan_text,
    ):
        enum_name = str(match.group("name") or "")
        open_brace = scan_text.find("{", match.start())
        close_brace = _matching_brace(scan_text, open_brace)
        if not enum_name or open_brace < 0 or close_brace <= open_brace:
            continue
        head = scan_text[open_brace + 1:close_brace]
        semicolon = head.find(";")
        if semicolon >= 0:
            head = head[:semicolon]
        for constant in re.finditer(
            r"(?m)(?:^|,)\s*(?P<name>[A-Z][A-Z0-9_$]*)\b",
            head,
        ):
            members.add(
                f"{enum_name}.{str(constant.group('name') or '')}"
            )
    return members


def _source_qualified_static_members(source_text: str) -> set[str]:
    """Return qualified constants backed by current callable/source evidence."""

    scan_text = _mask_java_literals(source_text)
    members = {
        f"{match.group('owner')}.{match.group('member')}"
        for match in _QUALIFIED_STATIC_MEMBER_RE.finditer(scan_text)
    }
    members.update(_enum_constant_members(source_text))
    for contract in _source_field_contracts(source_text):
        if (
            str(contract.get("access") or "package") != "private"
            and "static" in str(contract.get("modifiers") or "").split()
        ):
            owner = str(contract.get("owner") or "").rsplit(".", 1)[-1]
            name = str(contract.get("name") or "")
            if owner and name:
                members.add(f"{owner}.{name}")
    return members


def _source_qualified_static_member_type_contracts(
    source_text: str,
) -> dict[str, list[str]]:
    """Return exact declared types for visible qualified static members."""

    contracts: dict[str, list[str]] = {}
    for field in _source_field_contracts(source_text):
        if (
            str(field.get("access") or "package") == "private"
            or "static" not in str(field.get("modifiers") or "").split()
        ):
            continue
        owner = str(field.get("owner") or "").rsplit(".", 1)[-1]
        name = str(field.get("name") or "")
        java_type = _erased_simple_java_type(
            str(field.get("type") or "")
        )
        if not owner or not name or not java_type:
            continue
        values = contracts.setdefault(f"{owner}.{name}", [])
        if java_type not in values:
            values.append(java_type)
    for member in _enum_constant_members(source_text):
        owner = str(member).split(".", 1)[0]
        values = contracts.setdefault(member, [])
        if owner and owner not in values:
            values.append(owner)
    return contracts


def _source_visible_type_supertypes(
    source_text: str,
) -> dict[str, list[str]]:
    """Return source-declared direct/transitive supertype identities."""

    scan_text = _mask_java_comments(source_text)
    direct: dict[str, set[str]] = {}
    for match in _CLASS_DECL_RE.finditer(scan_text):
        subtype = _erased_simple_java_type(str(match.group("name") or ""))
        open_brace = scan_text.find("{", match.end())
        if not subtype or open_brace < 0:
            continue
        header = scan_text[match.end():open_brace]
        extends_match = re.search(
            r"\bextends\s+(?P<types>.*?)(?=\bimplements\b|$)",
            header,
            flags=re.DOTALL,
        )
        implements_match = re.search(
            r"\bimplements\s+(?P<types>.*?)$",
            header,
            flags=re.DOTALL,
        )
        for relation in (extends_match, implements_match):
            if relation is None:
                continue
            for raw_type in _split_java_top_level_commas(
                str(relation.group("types") or "")
            ):
                supertype = _erased_simple_java_type(raw_type)
                if supertype:
                    direct.setdefault(subtype, set()).add(supertype)
    expanded: dict[str, list[str]] = {}
    for subtype in direct:
        pending = list(direct.get(subtype) or [])
        seen: set[str] = set()
        while pending:
            current = pending.pop(0)
            if not current or current in seen or current == subtype:
                continue
            seen.add(current)
            pending.extend(direct.get(current) or [])
        expanded[subtype] = sorted(seen)
    return expanded


def _unverified_qualified_static_members(
    code: str,
    *,
    source_members: set[str],
) -> list[str]:
    references = {
        f"{match.group('owner')}.{match.group('member')}"
        for match in _QUALIFIED_STATIC_MEMBER_RE.finditer(
            _mask_java_literals(code)
        )
    }
    return sorted(references - set(source_members))


def _mask_java_comments(source: str) -> str:
    """Replace Java comments with spaces while preserving offsets/newlines."""

    text = str(source or "")
    out = list(text)
    state = "code"
    escaped = False
    index = 0
    while index < len(text):
        char = text[index]
        nxt = text[index + 1] if index + 1 < len(text) else ""
        if state == "line":
            if char == "\n":
                state = "code"
            else:
                out[index] = " "
            index += 1
            continue
        if state == "block":
            if char == "*" and nxt == "/":
                out[index] = " "
                out[index + 1] = " "
                state = "code"
                index += 2
                continue
            if char != "\n":
                out[index] = " "
            index += 1
            continue
        if state in {"string", "char"}:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif (
                state == "string" and char == '"'
            ) or (
                state == "char" and char == "'"
            ):
                state = "code"
            index += 1
            continue
        if char == "/" and nxt == "/":
            out[index] = " "
            out[index + 1] = " "
            state = "line"
            index += 2
            continue
        if char == "/" and nxt == "*":
            out[index] = " "
            out[index + 1] = " "
            state = "block"
            index += 2
            continue
        if char == '"':
            state = "string"
        elif char == "'":
            state = "char"
        index += 1
    return "".join(out)


def _entry_input_projection_is_statically_verified(
    *,
    selected_entry_contract: dict[str, Any] | None,
    entry_is_exact_target: bool,
) -> tuple[bool, str]:
    """Separate a callable wrapper from a proven target-input projection.

    A source-visible caller may skip, normalize, or dispatch public inputs
    before it reaches a private/internal target. Only direct target calls and
    uniquely resolved linear wrappers are deterministic proof. Callers with
    control flow require sandbox replay and candidate-level target coverage.
    """

    if entry_is_exact_target:
        return True, "direct_target_call"
    if not isinstance(selected_entry_contract, dict):
        return False, "entry_contract_missing"
    if str(selected_entry_contract.get("calls_target_via") or "") != "direct":
        return False, "transitive_entry_requires_replay"

    rows = [
        dict(row)
        for row in list(
            selected_entry_contract.get("target_call_argument_rows") or []
        )
        if isinstance(row, dict)
    ]
    if len(rows) != 1:
        return False, (
            "target_callsite_missing"
            if not rows
            else "multiple_target_callsites_require_replay"
        )

    row = rows[0]
    prefix = _mask_java_comments(
        str(row.get("caller_prefix_source_evidence") or "")
    )
    # Literal text is irrelevant to Java control flow and can contain words
    # such as "if" or "switch".
    scan_prefix = re.sub(
        r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'',
        '""',
        prefix,
    )
    if re.search(
        r"\b(?:if|switch|for|while|do|try|catch|finally|break|continue)\b|"
        r"\?|&&|\|\|",
        scan_prefix,
    ):
        return False, "caller_control_flow_requires_replay"

    caller_parameters = {
        str(name)
        for name in list(row.get("caller_parameter_names") or [])
        if str(name)
    }
    local_names = {
        str(match.group("name"))
        for match in re.finditer(
            r"(?m)^[ \t]*(?:final\s+)?"
            r"[A-Za-z_$][A-Za-z0-9_$<>\[\].?, \t]*\s+"
            r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*=",
            prefix,
        )
    }
    for raw_argument in list(row.get("arguments") or []):
        argument = str(raw_argument or "").strip()
        if not argument:
            return False, "target_argument_projection_missing"
        transparent_reference = _transparent_cast_reference(argument)
        if (
            argument in caller_parameters
            or argument in local_names
            or transparent_reference in caller_parameters
            or transparent_reference in local_names
        ):
            continue
        if _literal_value(argument) is not _UNKNOWN_LITERAL:
            continue
        return False, "target_argument_projection_not_linear"
    return True, "source_verified_linear_wrapper"


def _transparent_cast_reference(expression: str) -> str:
    """Return a bare source variable hidden only by Java reference casts."""

    text = str(expression or "").strip()
    cast_pattern = re.compile(
        r"^\(\s*"
        r"[A-Za-z_$][A-Za-z0-9_$.?]*"
        r"(?:\s*<[^(){};]{0,240}>)?"
        r"(?:\s*\[\s*\])*"
        r"\s*\)\s*(?P<value>.+)$",
        re.DOTALL,
    )
    for _ in range(4):
        match = cast_pattern.fullmatch(text)
        if match is None:
            break
        text = str(match.group("value") or "").strip()
    return text if re.fullmatch(r"[A-Za-z_$][A-Za-z0-9_$]*", text) else ""


def _extract_json_object(text: str) -> dict[str, Any]:
    raw = str(text or "").strip()
    if raw.startswith("```"):
        raw = re.sub(r"^```(?:json)?\s*", "", raw, flags=re.IGNORECASE)
        raw = re.sub(r"\s*```$", "", raw)
    try:
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else {}
    except json.JSONDecodeError:
        pass
    decoder = json.JSONDecoder()
    for index, char in enumerate(raw):
        if char != "{":
            continue
        try:
            parsed, _ = decoder.raw_decode(raw[index:])
        except json.JSONDecodeError:
            continue
        if isinstance(parsed, dict):
            return parsed
    return {}


def _extract_branch_payload(text: str) -> dict[str, Any]:
    """Parse a complete branch-analysis response without nested-object salvage."""

    raw = str(text or "").strip()
    if raw.startswith("```"):
        raw = re.sub(r"^```(?:json)?\s*", "", raw, flags=re.IGNORECASE)
        raw = re.sub(r"\s*```$", "", raw)
    try:
        parsed = json.loads(raw)
    except json.JSONDecodeError:
        return {}
    if not isinstance(parsed, dict) or not isinstance(parsed.get("branches"), list):
        return {}
    return parsed


def _branch_analysis_response_format(
    *,
    max_branches: int = 4,
) -> dict[str, Any]:
    """Return the structured-output contract for semantic branch analysis."""

    branch_properties: dict[str, Any] = {
        "branch_id": {"type": "string"},
        "anchor_line": {"type": "integer"},
        "branch_expression": {"type": "string"},
        "dependency_kind": {
            "type": "string",
            "enum": sorted(_DEPENDENCY_KINDS),
        },
        "required_state": {
            "type": "array",
            "maxItems": 8,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "symbol": {"type": "string"},
                    "constraint": {"type": "string"},
                    "source_evidence": {"type": "string"},
                },
                "required": [
                    "symbol",
                    "constraint",
                    "source_evidence",
                ],
            },
        },
        "field_relations": {
            "type": "array",
            "maxItems": 6,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "relation": {"type": "string"},
                    "source_evidence": {"type": "string"},
                },
                "required": ["relation", "source_evidence"],
            },
        },
        "external_dependencies": {
            "type": "array",
            "maxItems": 6,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "receiver": {"type": "string"},
                    "method": {"type": "string"},
                    "required_outcome": {"type": "string"},
                    "source_evidence": {"type": "string"},
                },
                "required": [
                    "receiver",
                    "method",
                    "required_outcome",
                    "source_evidence",
                ],
            },
        },
        "existing_green_scaffold_id": {"type": "string"},
        "entry_call": {"type": "string"},
        "setup_actions": {
            "type": "array",
            "maxItems": 16,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "call": {"type": "string"},
                    "source_evidence": {"type": "string"},
                },
                "required": ["call", "source_evidence"],
            },
        },
        "input_variants": {
            "type": "array",
            "maxItems": 6,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "value": {"type": "string"},
                    "purpose": {"type": "string"},
                    "source_evidence": {"type": "string"},
                },
                "required": [
                    "value",
                    "purpose",
                    "source_evidence",
                ],
            },
        },
        "observable_oracle": {"type": "string"},
        "opposite_outcome": {"type": "string"},
        "confidence": {
            "type": "number",
            "minimum": 0,
            "maximum": 1,
        },
    }
    return {
        "type": "json_schema",
        "json_schema": {
            "name": "tatg_branch_dependency_analysis",
            "strict": True,
            "schema": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "branches": {
                        "type": "array",
                        "maxItems": max(1, int(max_branches)),
                        "items": {
                            "type": "object",
                            "additionalProperties": False,
                            "properties": branch_properties,
                            "required": [
                                "branch_id",
                                "anchor_line",
                                "branch_expression",
                                "dependency_kind",
                                "required_state",
                                "field_relations",
                                "external_dependencies",
                                "existing_green_scaffold_id",
                                "entry_call",
                                "setup_actions",
                                "input_variants",
                                "observable_oracle",
                                "opposite_outcome",
                                "confidence",
                            ],
                        },
                    },
                    "uncertainties": {
                        "type": "array",
                        "maxItems": 8,
                        "items": {"type": "string"},
                    },
                },
                "required": ["branches", "uncertainties"],
            },
        },
    }


